import{_ as e,a,b as l,c as r,d as i}from"./chunks/cuav_v5_debug_cable.B_9f8mzs.js";import{_ as d,o,c as n,al as s}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"Порт для налагодження SWD","description":"","frontmatter":{},"headers":[],"relativePath":"uk/debug/swd_debug.md","filePath":"uk/debug/swd_debug.md"}'),h={name:"uk/debug/swd_debug.md"};function g(u,t,p,f,b,x){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="порт-для-налагодження-swd" tabindex="-1">Порт для налагодження SWD <a class="header-anchor" href="#порт-для-налагодження-swd" aria-label="Permalink to &quot;Порт для налагодження SWD&quot;">​</a></h1><p>PX4 runs on ARM Cortex-M microcontrollers, which contain dedicated hardware for interactive debugging via the <a href="https://support.arm.com/documentation/ihi0031/a/The-Serial-Wire-Debug-Port--SW-DP-" target="_blank" rel="noreferrer"><em>Serial Wire Debug (SWD)</em></a> interface and non-invasive profiling and high-bandwidth tracing via the <a href="https://support.arm.com/documentation/ddi0403/d/Appendices/Debug-ITM-and-DWT-Packet-Protocol?lang=en" target="_blank" rel="noreferrer"><em>Serial Wire Output (SWO)</em></a> and <a href="https://support.arm.com/documentation/ihi0064/latest/" target="_blank" rel="noreferrer"><em>TRACE</em> pins</a>.</p><p>Інтерфейс відладки SWD дозволяє прямий, низькорівневий, апаратний доступ до процесора мікроконтролера та периферійних пристроїв, тому він не залежить від будь-якого програмного забезпечення на пристрої. Отже, його можна використовувати для налагодження завантажувальних програм та операційних систем, таких як NuttX.</p><h2 id="debug-signals" tabindex="-1">Debug Signals <a class="header-anchor" href="#debug-signals" aria-label="Permalink to &quot;Debug Signals {#debug-signals}&quot;">​</a></h2><p>Чотири сигнали необхідні для відлагодження (в жирному шрифті), а решту лише рекомендується.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Назва</th><th style="text-align:left;">Тип</th><th style="text-align:left;">Опис</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>GND</strong></td><td style="text-align:left;">Power</td><td style="text-align:left;">Спільний потенціал, спільна основа.</td></tr><tr><td style="text-align:left;"><strong>VREF</strong></td><td style="text-align:left;">Power</td><td style="text-align:left;">Цільове довідкове напруга дозволяє засоби налагодження використовувати рівнеміри на сигнали.</td></tr><tr><td style="text-align:left;"><strong>SWDIO</strong></td><td style="text-align:left;">I/O</td><td style="text-align:left;">Пін даних для послідовного знавантаження через мережу.</td></tr><tr><td style="text-align:left;"><strong>SWCLK</strong></td><td style="text-align:left;">Вхід</td><td style="text-align:left;">Пін годинника для послідовного знавантаження через мережу.</td></tr><tr><td style="text-align:left;">nRST</td><td style="text-align:left;">Вхід</td><td style="text-align:left;">PIN скидання є необов’язковим (n = активним низьким).</td></tr><tr><td style="text-align:left;">SWO</td><td style="text-align:left;">Output</td><td style="text-align:left;">Однопровідний шлейф асинхронних даних з можливістю виведення даних ITM та DWT.</td></tr><tr><td style="text-align:left;">TRACECK</td><td style="text-align:left;">Output</td><td style="text-align:left;">Трасування годинника для паралельної шини.</td></tr><tr><td style="text-align:left;">TRACED[0-3]</td><td style="text-align:left;">Output</td><td style="text-align:left;">Трасування синхронної шини даних з 1, 2 чи 4 бітами.</td></tr></tbody></table><p>Пін скидання апаратного забезпечення є необов&#39;язковим, оскільки більшість пристроїв також можуть бути скинуті через лінії SWD. Однак швидке скидання пристрою за допомогою кнопки може бути великим плюсом для розробки.</p><p>SWO-пін може випромінювати дані профілювання в реальному часі з наносекундним відмітками часу, тому настійно рекомендується мати доступ до нього для відлагодження.</p><p>Піни TRACE потребують спеціалізованих засобів відлагодження для роботи з високою пропускною здатністю та наступним декодуванням потоку даних. Зазвичай вони недоступні і зазвичай використовуються лише для відлагодження дуже конкретних питань з часом.</p><h2 id="debug-ports" tabindex="-1">Autopilot Debug Ports <a class="header-anchor" href="#debug-ports" aria-label="Permalink to &quot;Autopilot Debug Ports {#debug-ports}&quot;">​</a></h2><p>Flight controllers commonly provide a single debug port that exposes both the <a href="#debug-signals">SWD Interface</a> and <a href="./system_console">System Console</a>.</p><p>The <a href="#pixhawk-standard-debug-ports">Pixhawk Connector Standards</a> formalize the port that must be used in each FMU version. However there are still many boards that use different pinouts or connectors, so we recommend you check the <a href="./../flight_controller/">documentation for your autopilot</a> to confirm port location and pinout.</p><p>The debug port location and pinouts for a subset of current autopilots are linked below:</p><p><a id="port-information"></a></p><table tabindex="0"><thead><tr><th style="text-align:left;">Автопілот</th><th style="text-align:left;">Відладочний порт</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./../flight_controller/pixhawk6x-rt#debug_port">Holybro Pixhawk 6X-RT</a> (FMUv6X-RT)</td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/pixhawk6x#debug_port">Holybro Pixhawk 6X</a> (FMUv6x)</td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/pixhawk5x#debug_port">Holybro Pixhawk 5X</a> (FMUv5x)</td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/durandal#debug-port">Holybro Durandal</a></td><td style="text-align:left;"><a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/pixhawk4#debug_port">Holybro Pixhawk 4</a> (FMUv5)</td><td style="text-align:left;"><a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/pixhawk6x_pro#debug-port">Holybro Pixhawk 6X Pro</a></td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/pixhawk6c#debug_port">Holybro Pixhawk 6C</a></td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/pixhawk6c_mini#debug_port">Holybro Pixhawk 6C Mini</a></td><td style="text-align:left;"><a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/holybro_pix32_v6#debug_port">Holybro Pix32 v6</a></td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/holybro_pix32_v5#debug-port">Holybro Pix32 v5</a></td><td style="text-align:left;"><a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/kakuteh7#debug-port">Holybro Kakute H7</a></td><td style="text-align:left;">SWD pads and system console</td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/kakuteh7mini#debug-port">Holybro Kakute H7 mini</a></td><td style="text-align:left;">SWD pads and system console</td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/kakuteh7v2#debug-port">Holybro Kakute H7 V2</a></td><td style="text-align:left;">SWD pads and system console</td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/cuav_pixhawk_v6x#debug_port">CUAV Pixhawk V6X</a></td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/cuav_x25-super#debug_port">CUAV X25-SUPER</a></td><td style="text-align:left;">[Pixhawk Debug Mini]</td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/cuav_x25-evo#debug_port">CUAV X25-EVO</a></td><td style="text-align:left;">[Pixhawk Debug Mini]</td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/cuav_nora#debug-port">CUAV Nora</a></td><td style="text-align:left;">Custom port but comes with adaptor cable.</td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/ark_pab#debug-port">ARK Pixhawk Autopilot Bus Carrier</a></td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/nxp_mr_vmu_rt1176#debug_port">NXP MR-VMU-RT1176</a></td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/pixracer#debug-port">mRo Pixracer</a></td><td style="text-align:left;"><a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a></td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/svehicle_e2#debug-port">S-Vehicle E2</a></td><td style="text-align:left;">[Pixhawk Debug Mini]</td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/x-mav_ap-h743r1#debug-port">AP-H743-R1</a></td><td style="text-align:left;">4-pin JST GH (SWD only)</td></tr><tr><td style="text-align:left;"><a href="./../flight_controller/mro_control_zero_f7#debug_port">mRo Control Zero F7</a></td><td style="text-align:left;"></td></tr></tbody></table><h2 id="pixhawk-standard-debug-ports" tabindex="-1">Pixhawk Connector Standard Debug Ports <a class="header-anchor" href="#pixhawk-standard-debug-ports" aria-label="Permalink to &quot;Pixhawk Connector Standard Debug Ports {#pixhawk-standard-debug-ports}&quot;">​</a></h2><p>Проект Pixhawk визначив стандартну схему виводів та тип роз&#39;єму для різних випусків Pixhawk FMU:</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Check your <a href="#port-information">specific board</a> to confirm the port used.</p></div><table tabindex="0"><thead><tr><th style="text-align:left;">Версія FMU</th><th style="text-align:left;">Версія Pixhawk</th><th style="text-align:left;">Відладочний порт</th></tr></thead><tbody><tr><td style="text-align:left;">FMUv2</td><td style="text-align:left;">Pixhawk / Pixhawk 1</td><td style="text-align:left;">10 pin ARM Debug</td></tr><tr><td style="text-align:left;">FMUv3</td><td style="text-align:left;">Pixhawk 2</td><td style="text-align:left;">6 pin SUR Debug</td></tr><tr><td style="text-align:left;">FMUv4</td><td style="text-align:left;">Pixhawk 3</td><td style="text-align:left;"><a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a></td></tr><tr><td style="text-align:left;">FMUv5</td><td style="text-align:left;">Pixhawk 4 FMUv5</td><td style="text-align:left;"><a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a></td></tr><tr><td style="text-align:left;">FMUv5X</td><td style="text-align:left;">Pixhawk 5X</td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;">FMUv6</td><td style="text-align:left;">Pixhawk 6</td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;">FMUv6X</td><td style="text-align:left;">Pixhawk 6X</td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr><tr><td style="text-align:left;">FMUv6X-RT</td><td style="text-align:left;">Pixhawk 6X-RT</td><td style="text-align:left;"><a href="#pixhawk-debug-full">Pixhawk Debug Full</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>There FMU and Pixhawk versions are (only) consistent after FMUv5X.</p></div><h3 id="pixhawk-debug-mini" tabindex="-1">Pixhawk Debug Mini <a class="header-anchor" href="#pixhawk-debug-mini" aria-label="Permalink to &quot;Pixhawk Debug Mini&quot;">​</a></h3><p>The <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Connector Standard</a> defines the <em>Pixhawk Debug Mini</em>, a <em>6-Pin SH Debug Port</em> that provides access to both SWD pins and the <a href="./system_console">System Console</a>.</p><p>Це використовується в FMUv4 та FMUv5.</p><p>Схема виводів показана нижче (виводи, необхідні для налагодження, виділені жирним шрифтом):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Pin</th><th style="text-align:left;">Сигнал</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:left;"><strong>VREF</strong></td></tr><tr><td style="text-align:right;">2</td><td style="text-align:left;">Console TX</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:left;">Console RX</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:left;"><strong>SWDIO</strong></td></tr><tr><td style="text-align:right;">5</td><td style="text-align:left;"><strong>SWDCLK</strong></td></tr><tr><td style="text-align:right;">6</td><td style="text-align:left;"><strong>GND</strong></td></tr></tbody></table><p>Визначення порту налагодження містить наступні припояні пластины (на платі поряд із роз&#39;ємом):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Pad</th><th style="text-align:left;">Сигнал</th><th style="text-align:left;">Напруга</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:left;">nRST</td><td style="text-align:left;">+3.3V</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:left;">GPIO1</td><td style="text-align:left;">+3.3V</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:left;">GPIO2</td><td style="text-align:left;">+3.3V</td></tr></tbody></table><p>The socket is a <em>6-pin JST SH</em> - Digikey number: <a href="https://www.digikey.com/en/products/detail/jst-sales-america-inc/BM06B-SRSS-TBT/1785724" target="_blank" rel="noreferrer">BM06B-SRSS-TBT(LF)(SN)</a> (vertical mount), <a href="https://www.digikey.com/en/products/detail/jst-sales-america-inc/SM06B-SRSS-TB/926712" target="_blank" rel="noreferrer">SM06B-SRSS-TBT(LF)(SN)</a> (side mount).</p><p>You can connect to the debug port using a <a href="https://www.digikey.com/en/products/detail/jst-sales-america-inc/A06SR06SR30K152A/6009379" target="_blank" rel="noreferrer">cable like this one</a>.</p><p><img src="'+e+'" alt="6-pin JST SH Cable"></p><h3 id="порти-відладки-pixhawk-full" tabindex="-1">Порти відладки Pixhawk Full <a class="header-anchor" href="#порти-відладки-pixhawk-full" aria-label="Permalink to &quot;Порти відладки Pixhawk Full&quot;">​</a></h3><p>The <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Connector Standard</a> defines <em>Pixhawk Debug Full</em>, a <em>10-Pin SH Debug Port</em> that provides access to both SWD pins and the <a href="./system_console">System Console</a>. This essentially moves the solder pads from beside the <a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a> into the connector, and also adds an SWO pin.</p><p>Цей порт вказаний для використання в FMUv5x, FMUv6, FMUv6x.</p><p>Схема виводів показана нижче (виводи, необхідні для налагодження, виділені жирним шрифтом):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Pin</th><th style="text-align:left;">Сигнал</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:left;"><strong>VREF</strong></td></tr><tr><td style="text-align:right;">2</td><td style="text-align:left;">Console TX</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:left;">Console RX</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:left;"><strong>SWDIO</strong></td></tr><tr><td style="text-align:right;">5</td><td style="text-align:left;"><strong>SWDCLK</strong></td></tr><tr><td style="text-align:right;">6</td><td style="text-align:left;">SWO</td></tr><tr><td style="text-align:right;">7</td><td style="text-align:left;">GPIO1</td></tr><tr><td style="text-align:right;">8</td><td style="text-align:left;">GPIO2</td></tr><tr><td style="text-align:right;">9</td><td style="text-align:left;">nRST</td></tr><tr><td style="text-align:right;">10</td><td style="text-align:left;"><strong>GND</strong></td></tr></tbody></table><p>Піни GPIO1/2 є вільними пінами, які можуть бути використані для генерації сигналів у програмному забезпеченні для аналізу часу з логічним аналізатором.</p><p>The socket is a <em>10-pin JST SH</em> - Digikey number: <a href="https://www.digikey.com/en/products/detail/jst-sales-america-inc/BM10B-SRSS-TB/926702" target="_blank" rel="noreferrer">BM10B-SRSS-TB(LF)(SN)</a> (vertical mount) or <a href="https://www.digikey.com/en/products/detail/jst-sales-america-inc/BM10B-SRSS-TB/926702" target="_blank" rel="noreferrer">SM10B-SRSS-TB(LF)(SN)</a> (side mount).</p><p>You can connect to the debug port using a <a href="https://www.digikey.com/products/en?keywords=A10SR10SR30K203A" target="_blank" rel="noreferrer">cable like this one</a>.</p><p><img src="'+a+'" alt="10-pin JST SH Cable"></p><h2 id="debug-probes" tabindex="-1">Debug Probes for PX4 Hardware <a class="header-anchor" href="#debug-probes" aria-label="Permalink to &quot;Debug Probes for PX4 Hardware {#debug-probes}&quot;">​</a></h2><p>Flight controllers commonly provide a <a href="#autopilot-debug-ports">single debug port</a> that exposes both the <a href="#debug-signals">SWD Interface</a> and <a href="./system_console">System Console</a>.</p><p>Є кілька зондів відлагодження, які були перевірені та підтримуються для підключення до одного або обох цих інтерфейсів:</p><ul><li><a href="./../debug/probe_jlink">SEGGER J-Link</a>: commercial probe, no built-in serial console, requires adapter.</li><li><a href="./../debug/probe_bmp">Black Magic Probe</a>: integrated GDB server and serial console, requires adapter.</li><li><a href="./../debug/probe_stlink">STLink</a>: best value, integrated serial console, adapter must be soldered.</li><li><a href="./../debug/probe_mculink">MCU-Link</a>: best value, integrated serial console, requires adapter.</li></ul><p>Адаптер для підключення до роз&#39;єму відладки може поставлятися разом із вашим контролером польоту або відлагоджувальним зондом. Інші варіанти наведено нижче.</p><h2 id="адаптери-для-відлагоджування" tabindex="-1">Адаптери для відлагоджування <a class="header-anchor" href="#адаптери-для-відлагоджування" aria-label="Permalink to &quot;Адаптери для відлагоджування&quot;">​</a></h2><h3 id="адаптер-відлагодження-holybro-pixhawk" tabindex="-1">Адаптер відлагодження Holybro Pixhawk <a class="header-anchor" href="#адаптер-відлагодження-holybro-pixhawk" aria-label="Permalink to &quot;Адаптер відлагодження Holybro Pixhawk&quot;">​</a></h3><p>The <a href="https://holybro.com/products/pixhawk-debug-adapter" target="_blank" rel="noreferrer">Holybro Pixhawk Debug Adapter</a> is <em>highly recommended</em> when debugging controllers that use one of the Pixhawk-standard debug connectors.</p><p>Це найлегший спосіб підключення:</p><ul><li>Flight controllers that use either the <a href="#pixhawk-debug-full">Pixhawk Debug Full</a> (10-pin SH) or <a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a> (6-pin SH) debug port.</li><li>SWD debug probes that support the 10-pin ARM compatible interface standard used by the <a href="./../debug/probe_jlink">Segger JLink EDU mini</a> or 20-pin compatible with the Segger JLink or STLink.</li></ul><p><img src="'+l+'" alt="Holybro Pixhawk Debug Adapter"></p><h3 id="адаптер-відлагодження-cuav-c-adb-pixhawk" tabindex="-1">Адаптер відлагодження CUAV C-ADB Pixhawk <a class="header-anchor" href="#адаптер-відлагодження-cuav-c-adb-pixhawk" aria-label="Permalink to &quot;Адаптер відлагодження CUAV C-ADB Pixhawk&quot;">​</a></h3><p>The <a href="https://store.cuav.net/shop/cuav-c-adb/" target="_blank" rel="noreferrer">CUAV C-ADB Secondary Development Pixhawk Flight Controller Debug Adapter</a> comes with an <a href="./../debug/probe_stlink">STLinkv3-MINIE Debug Probe</a>.</p><p>This has a ports for connecting to the <a href="#pixhawk-debug-full">Pixhawk Debug Full</a> (10-pin SH) and CUAV-standard DSU interface (but not the <a href="./../debug/swd_debug#pixhawk-debug-mini">Pixhawk Debug Mini</a> (6-pin SH)).</p><p>The M2 connector on the adaptor is 14-pin CN4 STDC14 (see the <a href="https://www.st.com/resource/en/user_manual/um2910-stlinkv3minie-debuggerprogrammer-tiny-probe-for-stm32-microcontrollers-stmicroelectronics.pdf" target="_blank" rel="noreferrer">STLinkv3-MINIE User Manual</a> for more information). Кабель, який використовується для підключення M2 та STLinkv3-MINIE, постачається з адаптером.</p><p><img src="'+r+'" alt="CUAV C-ADB adaptor connected to the STLinkv3-MINIE"></p><h3 id="адаптери-для-відлагоджування-1" tabindex="-1">Адаптери для відлагоджування <a class="header-anchor" href="#адаптери-для-відлагоджування-1" aria-label="Permalink to &quot;Адаптери для відлагоджування&quot;">​</a></h3><p>Some SWD <a href="#debug-probes">debug probes</a> come with adapters/cables for connecting to common Pixhawk <a href="#debug-ports">debug ports</a>. Зонди, про які відомо, що поставляються з роз&#39;ємами, перераховані нижче:</p><ul><li><a href="./../debug/probe_bmp#dronecode-probe">Zubax BugFace BF1</a>: comes with a connector for attaching to the <a href="#pixhawk-debug-mini">Pixhawk Debug Mini</a></li></ul><h3 id="адаптери-специфічні-для-плати" tabindex="-1">Адаптери, специфічні для плати <a class="header-anchor" href="#адаптери-специфічні-для-плати" aria-label="Permalink to &quot;Адаптери, специфічні для плати&quot;">​</a></h3><p>Some manufacturers provide cables to make it easy to connect the SWD interface and <a href="./../debug/system_console">System Console</a>.</p><p>For example, some CUAV board include this debug cable:</p><p><img src="'+i+'" alt="6-pin JST SH Cable"></p><h3 id="користувацькі-кабелі" tabindex="-1">Користувацькі кабелі <a class="header-anchor" href="#користувацькі-кабелі" aria-label="Permalink to &quot;Користувацькі кабелі&quot;">​</a></h3><p>Ви також можете створити власні кабелі для підключення до різних плат або зондів:</p><ul><li>Connect <code>SWDIO</code>, <code>SWCLK</code> and <code>GND</code> pins on the debug probe to the corresponding pins on the debug port.</li><li>Підключіть контакт VREF, якщо його підтримує засіб відлагодження.</li><li>Підключіть залишкові контакти, якщо вони є.</li></ul><p>See the <a href="./probe_stlink">STLinkv3-MINIE</a> for a guide on how to solder a custom cable.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Where possible, we highly recommend that you create or obtain an adapter board rather than custom cables for connecting to SWD/JTAG debuggers and computers. Це зменшує ризик неправильного підключення проводів, що призводить до проблем з налагодженням, і має перевагу в тому, що адаптери зазвичай надають спільний інтерфейс для підключення до кількох популярних плат керування польотом.</p></div>',67)])])}const m=d(h,[["render",g]]);export{k as __pageData,m as default};
